package com.saivandan.crm.api;
import com.saivandan.crm.domain.*; import com.saivandan.crm.repo.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/bookings") public class BookingController { private final BookingRepository bookings; private final LeadRepository leads; private final PropertyUnitRepository units; public BookingController(BookingRepository b,LeadRepository l,PropertyUnitRepository u){bookings=b;leads=l;units=u;} @GetMapping public List<Booking> list(){return bookings.findAllByOrderByBookingDateDesc();} @PostMapping public ResponseEntity<Booking> create(@Valid @RequestBody Request r){Lead l=leads.findById(r.leadId()).orElseThrow();PropertyUnit u=units.findById(r.unitId()).orElseThrow();if(u.getStatus()!=UnitStatus.AVAILABLE)return ResponseEntity.unprocessableEntity().build();u.setStatus(UnitStatus.SOLD);units.save(u);return ResponseEntity.status(HttpStatus.CREATED).body(bookings.save(new Booking(l,u,r.bookingAmount())));} public record Request(@NotNull Long leadId,@NotNull Long unitId,@NotNull @Min(1) Integer bookingAmount){} }
